+type Position = {
+  offset: number;
+  line: number;
+  column: number;
+};
+
+type Node = TextNode | VariableNode | BlockNode;
+
+type TextNode = { kind: "text"; value: string };
+type VariableNode = { kind: "variable"; path: string; escaped: boolean; position: Position };
+type BlockNode = {
+  kind: "block";
+  name: "if" | "each";
+  path: string;
+  truthy: Node[];
+  falsy: Node[];
+  hasElse: boolean;
+  position: Position;
+};
+
+type Frame = { nodes: Node[]; block?: BlockNode };
+type Context = { root: unknown; current: unknown; index?: number };
+
+function error(message: string, position: Position): Error {
+  return new Error(`${message} at line ${position.line}, column ${position.column}`);
+}
+
+function positionAt(template: string, offset: number): Position {
+  let line = 1;
+  let column = 1;
+  for (let i = 0; i < offset; i += 1) {
+    if (template[i] === "\n") {
+      line += 1;
+      column = 1;
+    } else {
+      column += 1;
+    }
+  }
+  return { offset, line, column };
+}
+
+function parse(template: string): Node[] {
+  const root: Node[] = [];
+  const frames: Frame[] = [{ nodes: root }];
+  let cursor = 0;
+
+  while (cursor < template.length) {
+    const start = template.indexOf("{{", cursor);
+    if (start === -1) {
+      if (cursor < template.length) frames.at(-1)!.nodes.push({ kind: "text", value: template.slice(cursor) });
+      break;
+    }
+    if (start > cursor) frames.at(-1)!.nodes.push({ kind: "text", value: template.slice(cursor, start) });
+
+    const triple = template.startsWith("{{{", start);
+    const openerLength = triple ? 3 : 2;
+    const closer = triple ? "}}}" : "}}";
+    const end = template.indexOf(closer, start + openerLength);
+    const position = positionAt(template, start);
+    if (end === -1) throw error("Unclosed tag", position);
+
+    const content = template.slice(start + openerLength, end).trim();
+    cursor = end + closer.length;
+
+    if (triple) {
+      if (!content) throw error("Interpolation path cannot be empty", position);
+      frames.at(-1)!.nodes.push({ kind: "variable", path: content, escaped: false, position });
+      continue;
+    }
+    if (!content || content.startsWith("!")) continue;
+
+    if (content === "else") {
+      const frame = frames.at(-1)!;
+      if (!frame.block) throw error("'else' is outside a block", position);
+      if (frame.block.hasElse) throw error("Duplicate 'else' in block", position);
+      frame.block.hasElse = true;
+      frame.nodes = frame.block.falsy;
+      continue;
+    }
+    if (content.startsWith("#")) {
+      const match = /^#(if|each)\s+(.+)$/.exec(content);
+      if (!match) throw error(`Unknown or malformed block '${content}'`, position);
+      const block: BlockNode = {
+        kind: "block",
+        name: match[1] as "if" | "each",
+        path: match[2].trim(),
+        truthy: [],
+        falsy: [],
+        hasElse: false,
+        position,
+      };
+      frames.at(-1)!.nodes.push(block);
+      frames.push({ nodes: block.truthy, block });
+      continue;
+    }
+    if (content.startsWith("/")) {
+      const name = content.slice(1).trim();
+      const frame = frames.at(-1)!;
+      if (!frame.block) throw error(`Unexpected closing block '${name}'`, position);
+      if (name !== frame.block.name) {
+        throw error(`Mismatched closing block '${name}', expected '${frame.block.name}'`, position);
+      }
+      frames.pop();
+      continue;
+    }
+    frames.at(-1)!.nodes.push({ kind: "variable", path: content, escaped: true, position });
+  }
+
+  if (frames.length > 1) {
+    const block = frames.at(-1)!.block!;
+    throw error(`Unclosed block '${block.name}'`, block.position);
+  }
+  return root;
