+
+function resolve(path: string, context: Context): unknown {
+  if (path === "this") return context.current;
+  if (path === "@index") return context.index;
+  if (!path || path.split(".").some((part) => !part)) return undefined;
+
+  let value: unknown = context.root;
+  for (const part of path.split(".")) {
+    if (value === null || value === undefined || (typeof value !== "object" && typeof value !== "function")) {
+      return undefined;
+    }
+    value = (value as Record<string, unknown>)[part];
+  }
+  return value;
+}
+
+function scalar(value: unknown, position: Position): string {
+  if (value === null || value === undefined) return "";
+  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean" || typeof value === "bigint") {
+    return String(value);
+  }
+  throw error("Cannot render an object or function as text", position);
+}
+
+function escapeHtml(value: string): string {
+  return value.replace(/[&<>"']/g, (character) => ({
+    "&": "&amp;",
+    "<": "&lt;",
+    ">": "&gt;",
+    '"': "&quot;",
+    "'": "&#39;",
+  })[character]!);
+}
+
+function isTruthy(value: unknown): boolean {
+  return !(value === false || value === null || value === undefined || value === 0 || value === "" || (Array.isArray(value) && value.length === 0));
+}
+
+function renderNodes(nodes: Node[], context: Context): string {
+  let output = "";
+  for (const node of nodes) {
+    if (node.kind === "text") output += node.value;
+    else if (node.kind === "variable") {
+      const value = scalar(resolve(node.path, context), node.position);
+      output += node.escaped ? escapeHtml(value) : value;
+    } else if (node.name === "if") {
+      output += renderNodes(isTruthy(resolve(node.path, context)) ? node.truthy : node.falsy, context);
+    } else {
+      const value = resolve(node.path, context);
+      if (Array.isArray(value) && value.length > 0) {
+        for (let index = 0; index < value.length; index += 1) {
+          output += renderNodes(node.truthy, { ...context, current: value[index], index });
+        }
+      } else {
+        output += renderNodes(node.falsy, context);
+      }
+    }
+  }
+  return output;
+}
+
+/** Renders a Mini Template string using the supplied root data object. */
+export function render(template: string, data: unknown): string {
+  return renderNodes(parse(template), { root: data, current: data });
+}

