+import { describe, expect, test } from "bun:test";
+import { render } from "../src/engine";
+
+describe("render", () => {
+  test("interpolates and HTML-escapes values", () => {
+    expect(render("Hello {{user.name}}: {{value}}", { user: { name: "Ada" }, value: "&<>\"'" })).toBe("Hello Ada: &amp;&lt;&gt;&quot;&#39;");
+    expect(render("{{{value}}}", { value: "<b>ok</b>" })).toBe("<b>ok</b>");
+  });
+
+  test("supports nested conditionals and falsey values", () => {
+    expect(render("{{#if a}}a{{#if b}}b{{else}}c{{/if}}{{else}}d{{/if}}", { a: true, b: false })).toBe("ac");
+    for (const value of ["", 0, false, null, undefined, []]) {
+      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("no");
+    }
+  });
+
+  test("iterates with this, index, root fallback, and nested loops", () => {
+    const template = "{{#each groups}}{{title}}:{{#each items}}[{{@index}}={{this}}/{{title}}]{{else}}empty{{/each}};{{else}}none{{/each}}";
