+  });
+
+  test("preserves text and omits comments and missing values", () => {
+    expect(render(" a\n{{! ignored }}{{missing}} b ", {})).toBe(" a\n b ");
+  });
+
+  test("rejects invalid templates and non-scalar interpolation", () => {
+    expect(() => render("{{#if ok}}", { ok: true })).toThrow(/Unclosed block.*line 1, column 1/);
+    expect(() => render("{{else}}", {})).toThrow(/outside a block.*line 1, column 1/);
+    expect(() => render("{{#if ok}}{{else}}{{else}}{{/if}}", { ok: true })).toThrow(/Duplicate/);
+    expect(() => render("{{#if ok}}{{/each}}", { ok: true })).toThrow(/Mismatched/);
+    expect(() => render("{{value}}", { value: {} })).toThrow(/Cannot render an object/);
+  });
+});

